import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"35、【晉】 坤下離上","description":"周易口訣義 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"周易口訣義 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/koujueyi/037.md","filePath":"classics/koujueyi/037.md"}'),r={name:"classics/koujueyi/037.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><p>彖曰：晉，進也。明出地上，順而麗乎大明，柔進而上行，是以「康侯用錫馬蕃庶，晝日三接」也。</p><p>象曰：明出地上，晉。君子以自昭明德。</p><p>初六：晉如摧如，貞吉。罔孚，裕無咎。</p><p>象曰：「晉如摧如」，獨行正也。「裕無咎」，未受命也。</p><p>六二：晉如愁如，貞吉。受茲介福，於其王母。</p><p>象曰：「受茲介福」，以中正也。</p><p>六三：眾允，悔亡。</p><p>象曰：眾允之志，上行也。</p><p>九四：晉如鼫鼠，貞厲。</p><p>象曰：鼫鼠貞厲，位不當也。</p><p>六五：悔亡，失得勿恤，往吉，無不利。</p><p>象曰：「失得勿恤」，往有慶也。</p><p>上九：晉其角，維用伐邑，厲吉無咎，貞吝。</p><p>象曰：「維用伐邑」，道未光也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',16)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
